void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    vec2 mouse = iMouse.xy / iResolution.xy ;
    //uv += mouse;
    uv -= vec2(0.5, 0.5);

    uv.x *= iResolution.x / iResolution.y;


    float radius = 0.20; 
    float exp_time = .4;
    float d = length(uv);
    float pi = 3.1415;
    vec2 main_vec = vec2(cos(iTime / exp_time), sin(iTime / exp_time));


    vec3 out_col  =  vec3(0.0, 0.0, 0.0);
    float radius_in_time  = radius ;//* abs(sin(iTime / exp_time));
    float c = abs(dot(uv, main_vec) / (d * length(main_vec)));
    if(length(uv) <  radius_in_time && c < (pi / 5.)) {
        out_col = vec3(cos(length(uv) / radius), 
                       sin(length(uv) / radius), 
                       0.0
                        );
        //out_col = smoothstep(radius_in_time, radius_in_time - 0.01, d);
    }




    // Output to screen
    fragColor = vec4(out_col, 1.0);
}
